import { memo, useEffect, useRef } from "react";
import type { CSSProperties } from "react";
import { Handle, Position } from "@xyflow/react";
import type { NodeProps } from "@xyflow/react";
import { theme, componentStyles, fontSize, FootprintIcon, useFootprintComponents, v } from "../../theme";
import { recordedPathLabel } from "../../trace/recordedValuePreview";

const KEYFRAMES_ID = "fp-stage-node-keyframes";
const KEYFRAMES_CSS = `
@media (prefers-reduced-motion: no-preference) {
  @keyframes fp-pulse {
    0%, 100% { opacity: var(--fp-node-pulse-opacity, 0.4); transform: scale(1); }
    50% { opacity: calc(var(--fp-node-pulse-opacity, 0.4) * 0.375); transform: scale(1.06); }
  }
  @keyframes fp-blink {
    0%, 100% { opacity: 1; }
    50% { opacity: 0.3; }
  }
}
@media (prefers-reduced-motion: reduce) {
  [data-fp="stage-node"], [data-fp="stage-node"] * {
    animation: none !important;
    transition: none !important;
  }
}
`;

const TRACE_VALUE_LIMIT = 1;
const GEOMETRY_STYLE_KEYS = new Set(["position", "inset", "top", "bottom", "left", "right", "width", "height", "minWidth", "maxWidth", "minHeight", "maxHeight", "display", "alignItems", "justifyContent", "flexDirection", "flexShrink", "overflow", "whiteSpace", "textOverflow", "transform", "zIndex", "pointerEvents", "boxSizing", "clipPath"]);
const traceText = (value: string, limit: number): string =>
  value.length > limit ? `${value.slice(0, limit - 1)}…` : value;

export interface StageNodeData {
  label: string;
  active?: boolean;
  done?: boolean;
  error?: boolean;
  linked?: boolean;
  /** Semantic icon hint (e.g., "llm", "tool", "rag", "start", "parse", "agent", "guard") */
  icon?: string;
  /** Step numbers in execution order (shown as badges — multiple when revisited via loops) */
  stepNumbers?: number[];
  /**
   * How many times this stage's execution was ATTEMPTED — a declared `retry`
   * policy that actually fired (footprintjs >= 9.15.0). Renders a small
   * warning-weight `↺ ×N` chip when greater than 1; 1 or absent renders
   * nothing, because one attempt is the silent default.
   *
   * Attempt telemetry, not an outcome. A stage that failed twice and then
   * succeeded is a DONE node wearing the chip; a stage that exhausted its
   * policy keeps its error state and wears the chip alongside. The chip
   * never changes the node's status colour.
   *
   * A policy that was DECLARED but never fired shows nothing at all —
   * declared is not the same as happened, and a chart that cannot tell the
   * two apart is worse than one that stays quiet.
   */
  retryAttempts?: number;
  /** Static evidence emphasis, independent of the node's execution status.
   * All presentation sits outside the card's layout footprint. */
  traceWorkflow?: {
    color: string;
    role: "question" | "input" | "upstream";
    values: readonly { key: string; preview: string | null; color: string }[];
  };
  /** Display membership only; makes no claim about execution or causal independence. */
  traceContext?: "displayed" | "outside";
  /** Keep content, semantic hooks and ports; let the host supply visual styles. */
  unstyled?: boolean;
  /** Stop node pulses and state transitions while inspecting recorded evidence. */
  suppressMotion?: boolean;
  /** Node was not executed (dim it) */
  dimmed?: boolean;
  /** Node is a subflow root (show nested indicator) */
  isSubflow?: boolean;
  /** Node uses lazy resolution (dashed border + cloud icon when unresolved) */
  isLazy?: boolean;
  /** Node is a decider (renders as diamond shape per flowchart convention) */
  isDecider?: boolean;
  /** Node is a fork (parallel fan-out) */
  isFork?: boolean;
  /** Human-readable description of what this stage does */
  description?: string;
  /** Subflow identifier — set when this node belongs to a subflow */
  subflowId?: string;
  /**
   * Stable stage identifier from the spec (`SpecNode.id`). Renderable as a
   * small monospace caption under the label when `showStageId` is true —
   * useful for teaching the runtimeStageId convention and for debugging
   * which node a recorder event belongs to.
   */
  stageId?: string;
  /**
   * When true, render the `stageId` as a small monospace caption beneath
   * the label. Default false. Drives the "Show IDs" toggle in
   * ExplainableShell.
   */
  showStageId?: boolean;
  /**
   * Visual emphasis hint — generic, so the renderer stays domain-agnostic.
   * `hero` = a stage the viewer cares about (accent border + tint + bold);
   * `muted` = mechanism/plumbing (recedes — faded + thin border). The
   * consumer's graph builder sets this from its own semantics (e.g. the
   * agentfootprint lens maps `stageRole` → emphasis). Layers UNDER run status:
   * active/done/error colours still override during a run.
   */
  emphasis?: "hero" | "muted";
  /**
   * Size tier — scales the card's text + padding to match the footprint the
   * layout allocated (the layout's node-size resolver must scale in lockstep,
   * else the card and its laid-out box disagree). `lg` = a focal stage,
   * `sm` = a minor/plumbing stage, default `md`. Generic — no domain meaning.
   */
  size?: "sm" | "md" | "lg";
  [key: string]: unknown;
}

// ── Stage icon SVGs ───────────────────────────────────────────────────────
// Inline SVGs for crisp rendering at any size. Consumers pass a string key
// via SpecNode.icon; StageNode renders the matching mini-icon.

const ICON_SIZE = 16;

function StageIcon({ type, color, size, unstyled }: { type: string; color: string; size?: string; unstyled: boolean }) {
  const customIcon = useFootprintComponents().Icon;
  const s = ICON_SIZE;
  const props = { width: s, height: s, viewBox: `0 0 ${s} ${s}`, fill: "none", style: { flexShrink: 0, ...(size && { width: size, height: size }) } as const };

  const glyph = (() => { switch (type) {
    // LLM / AI call — brain/sparkle
    case "llm":
    case "ai":
      return (
        <svg {...props}>
          <circle cx="8" cy="8" r="6" stroke={color} strokeWidth="1.5" />
          <path d="M5.5 8C5.5 6.5 6.5 5 8 5S10.5 6.5 10.5 8" stroke={color} strokeWidth="1.2" strokeLinecap="round" />
          <circle cx="8" cy="9.5" r="1" fill={color} />
          <line x1="8" y1="2" x2="8" y2="3.5" stroke={color} strokeWidth="1" strokeLinecap="round" />
          <line x1="12.5" y1="4" x2="11.2" y2="5" stroke={color} strokeWidth="1" strokeLinecap="round" />
          <line x1="3.5" y1="4" x2="4.8" y2="5" stroke={color} strokeWidth="1" strokeLinecap="round" />
        </svg>
      );

    // Tool / function call — gear
    case "tool":
    case "function":
      return (
        <svg {...props}>
          <circle cx="8" cy="8" r="3" stroke={color} strokeWidth="1.5" />
          {[0, 45, 90, 135, 180, 225, 270, 315].map((angle) => {
            const rad = (angle * Math.PI) / 180;
            const x1 = 8 + Math.cos(rad) * 4.5;
            const y1 = 8 + Math.sin(rad) * 4.5;
            const x2 = 8 + Math.cos(rad) * 6;
            const y2 = 8 + Math.sin(rad) * 6;
            return <line key={angle} x1={x1} y1={y1} x2={x2} y2={y2} stroke={color} strokeWidth="1.5" strokeLinecap="round" />;
          })}
        </svg>
      );

    // RAG / retrieval — magnifying glass + doc
    case "rag":
    case "search":
    case "retrieval":
      return (
        <svg {...props}>
          <circle cx="7" cy="7" r="4" stroke={color} strokeWidth="1.5" />
          <line x1="10" y1="10" x2="13.5" y2="13.5" stroke={color} strokeWidth="1.5" strokeLinecap="round" />
          <line x1="5.5" y1="6" x2="8.5" y2="6" stroke={color} strokeWidth="1" strokeLinecap="round" />
          <line x1="5.5" y1="8" x2="7.5" y2="8" stroke={color} strokeWidth="1" strokeLinecap="round" />
        </svg>
      );

    // Parse / process — diamond with arrows
    case "parse":
    case "process":
    case "transform":
      return (
        <svg {...props}>
          <rect x="4" y="4" width="8" height="8" rx="1.5" stroke={color} strokeWidth="1.5" transform="rotate(45 8 8)" />
        </svg>
      );

    // Start / seed — play triangle
    case "start":
    case "seed":
    case "init":
      return (
        <svg {...props}>
          <path d="M5 3.5L12.5 8L5 12.5V3.5Z" fill={color} opacity="0.8" />
        </svg>
      );

    // End / finalize — stop square
    case "end":
    case "finalize":
    case "output":
      return (
        <svg {...props}>
          <rect x="4" y="4" width="8" height="8" rx="1.5" fill={color} opacity="0.8" />
        </svg>
      );

    // Agent — person silhouette
    case "agent":
    case "orchestrator":
      return (
        <svg {...props}>
          <circle cx="8" cy="5" r="2.5" stroke={color} strokeWidth="1.5" />
          <path d="M3.5 14C3.5 11 5.5 9 8 9S12.5 11 12.5 14" stroke={color} strokeWidth="1.5" strokeLinecap="round" />
        </svg>
      );

    // Swarm — multi-agent
    case "swarm":
    case "multi-agent":
      return (
        <svg {...props}>
          <circle cx="5" cy="5" r="2" stroke={color} strokeWidth="1.2" />
          <circle cx="11" cy="5" r="2" stroke={color} strokeWidth="1.2" />
          <circle cx="8" cy="11" r="2" stroke={color} strokeWidth="1.2" />
          <line x1="5" y1="7" x2="8" y2="9" stroke={color} strokeWidth="1" opacity="0.5" />
          <line x1="11" y1="7" x2="8" y2="9" stroke={color} strokeWidth="1" opacity="0.5" />
        </svg>
      );

    // Guard / guardrail — shield
    case "guard":
    case "guardrail":
    case "validate":
      return (
        <svg {...props}>
          <path d="M8 2L3 5V9C3 11.5 5 13.5 8 14.5C11 13.5 13 11.5 13 9V5L8 2Z" stroke={color} strokeWidth="1.5" strokeLinejoin="round" />
          <path d="M6 8L7.5 9.5L10 6.5" stroke={color} strokeWidth="1.2" strokeLinecap="round" strokeLinejoin="round" />
        </svg>
      );

    // Stream — wave
    case "stream":
    case "streaming":
      return (
        <svg {...props}>
          <path d="M2 8C4 5 6 11 8 8S12 5 14 8" stroke={color} strokeWidth="1.5" strokeLinecap="round" fill="none" />
          <path d="M2 11C4 8 6 14 8 11S12 8 14 11" stroke={color} strokeWidth="1" strokeLinecap="round" fill="none" opacity="0.5" />
        </svg>
      );

    // Memory / state — database cylinder
    case "memory":
    case "state":
    case "db":
      return (
        <svg {...props}>
          <ellipse cx="8" cy="4.5" rx="5" ry="2" stroke={color} strokeWidth="1.3" />
          <line x1="3" y1="4.5" x2="3" y2="11.5" stroke={color} strokeWidth="1.3" />
          <line x1="13" y1="4.5" x2="13" y2="11.5" stroke={color} strokeWidth="1.3" />
          <ellipse cx="8" cy="11.5" rx="5" ry="2" stroke={color} strokeWidth="1.3" />
        </svg>
      );

    // System prompt — document with lines
    case "system-prompt":
    case "prompt":
    case "instructions":
    case "document":
      return (
        <svg {...props}>
          <rect x="3.5" y="2" width="9" height="12" rx="1.5" stroke={color} strokeWidth="1.3" fill="none" />
          <line x1="5.5" y1="5" x2="10.5" y2="5" stroke={color} strokeWidth="1" strokeLinecap="round" />
          <line x1="5.5" y1="7.5" x2="10.5" y2="7.5" stroke={color} strokeWidth="1" strokeLinecap="round" />
          <line x1="5.5" y1="10" x2="8.5" y2="10" stroke={color} strokeWidth="1" strokeLinecap="round" />
        </svg>
      );

    // Messages / conversation — chat bubble
    case "messages":
    case "chat":
    case "conversation":
      return (
        <svg {...props}>
          <rect x="2.5" y="3" width="11" height="8" rx="2" stroke={color} strokeWidth="1.3" fill="none" />
          <path d="M5.5 11L5.5 13.5L8.5 11" stroke={color} strokeWidth="1.3" strokeLinecap="round" strokeLinejoin="round" fill="none" />
          <line x1="5" y1="6" x2="11" y2="6" stroke={color} strokeWidth="1" strokeLinecap="round" />
          <line x1="5" y1="8.5" x2="9" y2="8.5" stroke={color} strokeWidth="1" strokeLinecap="round" />
        </svg>
      );

    // Loop — circular arrow
    case "loop":
    case "retry":
      return (
        <svg {...props}>
          <path d="M12 8A4 4 0 1 1 8 4" stroke={color} strokeWidth="1.5" strokeLinecap="round" fill="none" />
          <path d="M8 1.5L10.5 4L8 6.5" stroke={color} strokeWidth="1.3" strokeLinecap="round" strokeLinejoin="round" fill="none" />
        </svg>
      );

    // Lazy / service — cloud (deferred resolution, loaded on demand)
    case "lazy":
    case "service":
    case "cloud":
      return (
        <svg {...props}>
          <path
            d="M4.5 12C2.8 12 1.5 10.7 1.5 9C1.5 7.5 2.5 6.3 3.8 6C4 4 5.8 2.5 8 2.5C9.8 2.5 11.3 3.5 11.9 5C13.9 5.2 15.5 6.8 15.5 8.8C15.5 10.8 13.9 12.5 11.8 12.5H4.5"
            stroke={color}
            strokeWidth="1.3"
            strokeLinecap="round"
            fill="none"
          />
        </svg>
      );

    // Decision — diamond (already handled by isDecider shape)
    case "decision":
    case "router":
      return (
        <svg {...props}>
          <path d="M8 2L14 8L8 14L2 8Z" stroke={color} strokeWidth="1.5" fill="none" />
          <circle cx="8" cy="8" r="1.5" fill={color} />
        </svg>
      );

    default:
      return null;
  } })();
  if (!glyph && !customIcon) return null;
  return <FootprintIcon name={type} part="stage-icon" unstyled={unstyled}
    style={{ flexShrink: 0 }} defaultStyle={{ display: "inline-flex", alignItems: "center", justifyContent: "center", color, width: size, height: size }}>
    {glyph}
  </FootprintIcon>;
}

/**
 * Custom ReactFlow node for pipeline stages.
 * All colors and fonts come from `--fp-*` CSS variables (via theme).
 * Shows execution state via color, icon, step badge, and pulse animation.
 */
export const StageNode = memo(function StageNode({
  data,
}: NodeProps & { data: StageNodeData }) {
  const { label, active, done, error, linked, icon, stepNumbers, dimmed, isSubflow, isLazy, isDecider, isFork, description, stageId, showStageId, retryAttempts, traceWorkflow, traceContext, suppressMotion } = data;
  const displayedContext = traceContext ?? (traceWorkflow ? "displayed" : undefined);
  const viewingTrace = displayedContext !== undefined;
  const unstyled = data.unstyled === true;
  const density = data.size === "sm" ? "compact" : data.size === "lg" ? "detailed" : "default";
  const metrics = componentStyles(density);
  const iconFootprint = `calc(${metrics.iconSize} + ${2 - (fontSize[density].body - fontSize.default.body)}px)`;
  const offset = (base: string, delta: number) => delta === 0 ? base
    : `calc(${base} ${delta < 0 ? "-" : "+"} ${Math.abs(delta)}px)`;
  const sx = (styles: CSSProperties): CSSProperties => {
    if (unstyled) return Object.fromEntries(Object.entries(styles).filter(([key]) => GEOMETRY_STYLE_KEYS.has(key)));
    return { ...styles,
      ...(typeof styles.fontSize === "number" && { fontSize: `calc(${metrics.body} + ${styles.fontSize - fontSize[density].body}px)` }),
      ...(styles.fontWeight === 400 && { fontWeight: metrics.weightNormal }),
      ...(styles.fontWeight === 500 && { fontWeight: metrics.weightMedium }),
      ...(typeof styles.fontWeight === "number" && styles.fontWeight >= 600 && {
        fontWeight: styles.fontWeight === 700 ? metrics.weightStrong
          : `calc(${metrics.weightStrong} ${styles.fontWeight < 700 ? "-" : "+"} ${Math.abs(styles.fontWeight - 700)})`,
      }),
      ...(typeof styles.gap === "number" && { gap: offset(metrics.controlGap, styles.gap - 6) }),
      ...(typeof styles.borderRadius === "number" && { borderRadius: offset(metrics.radiusControl, styles.borderRadius - 6) }),
      ...(typeof styles.padding === "string" && /^\d+px(?: \d+px)*$/.test(styles.padding) && {
        padding: styles.padding.split(" ").map(part => offset(metrics.spaceMd, Number.parseInt(part, 10) - 12)).join(" "),
      }),
    };
  };

  // Lazy nodes show cloud icon by default (unless another icon is specified)
  const effectiveIcon = icon || (isLazy ? "lazy" : undefined);
  // Lazy + unresolved = dashed border
  const isLazyUnresolved = isLazy && !done && !active;

  // Inject keyframes once into document head
  const injectedRef = useRef(false);
  useEffect(() => {
    if (unstyled) return;
    if (injectedRef.current) return;
    if (typeof document !== "undefined" && !document.getElementById(KEYFRAMES_ID)) {
      const styleEl = document.createElement("style");
      styleEl.id = KEYFRAMES_ID;
      styleEl.textContent = KEYFRAMES_CSS;
      document.head.appendChild(styleEl);
    }
    injectedRef.current = true;
  }, [unstyled]);

  const isOnPath = active || done;

  // Attempt chip. Shown only when the stage genuinely ran more than once —
  // the same threshold the overlay applies, restated here so a consumer
  // handing `data` in directly gets the same rule.
  const showRetryBadge = typeof retryAttempts === "number" && retryAttempts > 1;
  // Honest either way: the chip says how many attempts were made and how the
  // LAST one ended. `error` is the node's own run status, so a stage that
  // exhausted its policy reads "failed" and one that recovered reads
  // "succeeded" — the chip never has to guess.
  const retryLabel = showRetryBadge
    ? `retried, attempt ${retryAttempts} of ${retryAttempts} ${error ? "failed" : "succeeded"}`
    : undefined;

  // Emphasis (importance hierarchy). Generic flags — no domain knowledge.
  const isHero = data.emphasis === "hero";
  const isMuted = data.emphasis === "muted";
  // Card text/padding scale — kept in step with the layout's footprint resolver.
  const sizeScale = data.size === "lg" ? 1.3 : data.size === "sm" ? 0.85 : 1;

  // RESTING (not-yet-run) appearance carries the importance hierarchy: heroes
  // get an accent border + faint accent tint + accent glow. Run status
  // (active/done/error) overrides these during execution.
  // THREE semantic node-state colors (themeable): the scrub CURSOR (active), the
  // VISITED path (done), and a group's MAIN/hero node. Error keeps its own red.
  const restingBg = isHero
    ? `color-mix(in srgb, ${theme.nodeMain} 12%, ${theme.bgSecondary})`
    : theme.bgSecondary;
  const restingBorder = isHero ? theme.nodeMain : theme.border;
  const restingShadow = isHero
    ? `0 0 10px color-mix(in srgb, ${theme.nodeMain} 22%, transparent)`
    : `0 2px 8px rgba(0,0,0,0.15)`;

  // Priority: cursor (amber) > a MAIN node (indigo — even after it ran, so the
  // lead nodes stay a distinct 3rd colour and don't all collapse to green) >
  // visited (green) > error (red) > resting.
  const bg = active
    ? theme.nodeCursor
    : isHero && done
      ? theme.nodeMain
      : done
        ? theme.nodeVisited
        : error
          ? theme.error
          : restingBg;

  const legacyBorderColor = active
    ? theme.nodeCursor
    : isHero && done
      ? theme.nodeMain
      : done
        ? theme.nodeVisited
        : error
          ? theme.error
          : restingBorder;

  const legacyShadow = active
    ? `0 0 22px color-mix(in srgb, ${theme.nodeCursor} 55%, transparent)`
    : isHero && done
      ? `0 0 12px color-mix(in srgb, ${theme.nodeMain} 30%, transparent)`
      : done
        ? `0 0 8px color-mix(in srgb, ${theme.nodeVisited} 20%, transparent)`
        : error
          ? `0 0 12px color-mix(in srgb, ${theme.error} 30%, transparent)`
          : restingShadow;

  // Optional chart-paint overrides keep the per-state recipes below as their
  // fallbacks. A preset's `initial` reset selects those original recipes.
  const borderColor = v("--fp-node-border-color", legacyBorderColor);
  const borderWidth = v("--fp-node-border-width", isHero ? "2.5px" : isMuted ? "1px" : "2px");
  const borderStyle = isLazyUnresolved ? "dashed" : v("--fp-node-border-style", "solid");
  const nodeRadius = v("--fp-node-radius", theme.radius);
  const shadow = v("--fp-node-shadow", legacyShadow);

  // Text contrast per state. The CURSOR color (nodeCursor) is a light amber by
  // design, so it needs DARK text (white washes out on amber — that's the "Final
  // node unreadable" regression). done (green) / error (red) are dark enough for
  // white. Resting uses the consumer's text color.
  const textColor = unstyled ? "currentColor" : active ? theme.onNodeCursor
    : done ? isHero ? theme.onNodeMain : theme.onNodeVisited
    : error ? theme.onNodeError : theme.textPrimary;

  return (
    <>
      <Handle type="target" position={Position.Top} style={sx({ opacity: 0 })} />
      {/* Centering wrapper. React Flow sizes the node WRAPPER to the layout's
          allocated width (which may be WIDER than the card — e.g. uniform-width
          columns, or a NodeSizeResolver footprint stamped by the layout). The
          card below is content-sized; without this wrapper it sits at the
          wrapper's LEFT edge, so its visual center drifts left of the box
          center the layout placed it at (the wider the box, the worse the
          drift). `width:100%` + center-justify makes the card's visual center
          coincide with the node-box center, so layout centering == paint
          centering. Mirrors SlotPillNode / GroupContainerNode, which already
          fill their wrapper width. */}
      <div
        data-fp="stage-node"
        data-active={active || undefined}
        data-done={done || undefined}
        data-error={error || undefined}
        data-unstyled={unstyled || undefined}
        data-trace-role={traceWorkflow?.role}
        data-trace-context={displayedContext}
        title={displayedContext === "outside" ? "Outside displayed trace. Recorded execution status is shown independently."
          : displayedContext === "displayed" ? "In displayed trace. Recorded execution status is shown independently." : undefined}
        data-motion-suppressed={suppressMotion || undefined}
        style={sx({ width: "100%", display: "flex", justifyContent: "center" })}
      >
        <div
          style={sx({
            position: "relative",
            display: "flex",
            alignItems: "center",
            gap: 6,
            // Trace emphasis uses rings and read links; every stage label stays readable.
            opacity: viewingTrace ? 1 : isMuted ? 0.5 : undefined,
          })}
        >
          {/* Evidence is an absolute overlay: run status, measured dimensions
              and the target/source handles keep their existing meaning. */}
          {traceWorkflow && <>
            {isDecider ? <svg
              data-fp="trace-workflow-ring"
              aria-hidden="true"
              viewBox="0 0 100 100"
              preserveAspectRatio="none"
              style={sx({ position: "absolute", inset: -8, width: "calc(100% + 16px)", height: "calc(100% + 16px)", overflow: "visible", pointerEvents: "none", zIndex: 3 })}
            ><polygon points="50,0 100,50 50,100 0,50" fill="none" stroke={unstyled ? "currentColor" : traceWorkflow.color} strokeWidth={unstyled ? undefined : 3} vectorEffect="non-scaling-stroke" /></svg> : <div
              data-fp="trace-workflow-ring"
              aria-hidden="true"
              style={sx({ position: "absolute", inset: -8, border: `3px solid ${traceWorkflow.color}`, borderRadius: `calc(${nodeRadius} + 6px)`, pointerEvents: "none", zIndex: 3 })}
            />}
            <div
              data-fp="trace-workflow-caption"
              style={sx({ position: "absolute", left: "50%", top: "calc(100% + 7px)", transform: "translateX(-50%)", zIndex: 12, display: "flex", alignItems: "center", gap: 4, width: "max-content", maxWidth: 220, height: 18, boxSizing: "border-box", overflow: "hidden", padding: "1px 5px", border: `1px solid ${traceWorkflow.color}`, borderRadius: 5, background: theme.bgSecondary, fontFamily: theme.fontSans, fontSize: 9, lineHeight: "14px", whiteSpace: "nowrap", pointerEvents: "none" })}
            >
              <span data-fp="trace-workflow-role" style={sx({ flexShrink: 0, color: traceWorkflow.color, fontWeight: 700 })}>
                {traceWorkflow.role === "question" ? "Question" : traceWorkflow.role === "input" ? "Recorded input" : "Upstream read"}
              </span>
              {traceWorkflow.values.length > 0 && <>
                <span aria-hidden="true" style={sx({ color: theme.textSecondary })}>·</span>
                <span data-fp="trace-workflow-values" style={sx({ display: "flex", alignItems: "center", minWidth: 0, overflow: "hidden" })}>
                  {traceWorkflow.values.slice(0, TRACE_VALUE_LIMIT).map((value, index) => <span
                    key={`${index}:${value.key}`}
                    data-fp="trace-workflow-value"
                    style={sx({ minWidth: 0, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap", color: value.color, fontFamily: "ui-monospace, monospace", fontWeight: 600 })}
                  >{traceText(recordedPathLabel(value.key), 32)}{value.preview === null ? " · preview unavailable" : ` = ${traceText(value.preview, 48)}`}</span>)}
                </span>
                {traceWorkflow.values.length > TRACE_VALUE_LIMIT && <span data-fp="trace-workflow-more" style={sx({ flexShrink: 0, color: theme.textSecondary })}>+{traceWorkflow.values.length - TRACE_VALUE_LIMIT} more</span>}
              </>}
            </div>
          </>}
          {displayedContext === "outside" && <div
            data-fp="trace-context-caption"
            style={sx({ position: "absolute", left: "calc(50% + 12px)", top: "calc(100% + 7px)", zIndex: 12,
              width: "max-content", maxWidth: 220, height: 18, boxSizing: "border-box", overflow: "hidden",
              textOverflow: "ellipsis", padding: "1px 5px", border: `1px solid ${theme.border}`, borderRadius: 5,
              background: theme.bgSecondary, color: theme.textSecondary, fontFamily: theme.fontSans, fontSize: 9,
              lineHeight: "14px", whiteSpace: "nowrap", pointerEvents: "none" })}
          >Outside displayed trace</div>}
          {/* Step number badges — multiple when revisited via loops */}
          {stepNumbers && stepNumbers.length > 0 && isOnPath && (
            <div
              style={sx({
                position: "absolute",
                top: -10,
                left: -10,
                display: "flex",
                gap: 3,
                zIndex: 10,
              })}
            >
              {stepNumbers.map((num, i) => {
                const isLatest = i === stepNumbers.length - 1;
                const badgeBg = isLatest && active ? theme.nodeCursor : theme.nodeVisited;
                const glow = isLatest && active
                  ? `color-mix(in srgb, ${theme.nodeCursor} 50%, transparent)`
                  : `color-mix(in srgb, ${theme.nodeVisited} 40%, transparent)`;
                return (
                  <div
                    key={num}
                    style={sx({
                      width: 22,
                      height: 22,
                      borderRadius: "50%",
                      background: badgeBg,
                    color: isLatest && active ? theme.onNodeCursor : theme.onNodeVisited,
                      fontSize: 11,
                      fontWeight: 700,
                      display: "flex",
                      alignItems: "center",
                      justifyContent: "center",
                      boxShadow: v("--fp-node-badge-shadow", `0 0 8px ${glow}`),
                    })}
                  >
                    {num}
                  </div>
                );
              })}
            </div>
          )}

          {/* Linked pulse ring */}
          {linked && (
            <div
              style={sx({
                position: "absolute",
                inset: -6,
                borderRadius: isDecider ? 0 : `calc(${nodeRadius} + 4px)`,
                clipPath: isDecider ? "polygon(50% 0%, 100% 50%, 50% 100%, 0% 50%)" : undefined,
                border: `2px solid ${theme.primary}`,
                opacity: v("--fp-node-pulse-opacity", "0.4"),
                animation: suppressMotion ? "none" : "fp-pulse 2s ease-in-out infinite",
              })}
            />
          )}

          {/* Active node pulse ring */}
          {active && (
            <div
              style={sx({
                position: "absolute",
                inset: -6,
                borderRadius: isDecider ? 0 : `calc(${nodeRadius} + 4px)`,
                clipPath: isDecider ? "polygon(50% 0%, 100% 50%, 50% 100%, 0% 50%)" : undefined,
                border: `2px solid ${theme.nodeCursor}`,
                opacity: v("--fp-node-pulse-opacity", "0.3"),
                animation: suppressMotion ? "none" : "fp-pulse 1.5s ease-out infinite",
              })}
            />
          )}

          {/* The cursor is a viewed recorded step while tracing. Sits top-right
              so it never collides with the top-left step-number badge. */}
          {active && (
            <div
              data-fp="stage-cursor-badge"
              style={sx({
                position: "absolute",
                top: -9,
                right: -8,
                zIndex: 11,
                background: theme.nodeCursor,
                color: theme.onNodeCursor,
                fontSize: 9,
                fontWeight: 800,
                letterSpacing: 0.6,
                padding: "2px 6px",
                borderRadius: 10,
                boxShadow: v("--fp-node-badge-shadow", `0 0 10px color-mix(in srgb, ${theme.nodeCursor} 60%, transparent)`),
              })}
            >
              {viewingTrace ? "VIEWING" : "NOW"}
            </div>
          )}

          {/* Attempt chip — a retried stage says so on the CHART, not only in
              the story. Bottom-right so it never collides with the NOW badge
              (top-right) or the step-number badges (top-left), and outside the
              shape layer so the diamond and the rectangle wear it identically.
              Outlined in warning weight to agree with the narrative's `retry`
              row (StoryNarrative's retry icon + theme.warning) — the same
              fact, drawn the same colour, on two surfaces. */}
          {showRetryBadge && (
            <div
              role="img"
              aria-label={retryLabel}
              title={retryLabel}
              style={sx({
                position: "absolute",
                bottom: -9,
                right: -8,
                zIndex: 11,
                display: "flex",
                alignItems: "center",
                gap: 2,
                background: theme.bgSecondary,
                border: `1px solid ${theme.warning}`,
                color: theme.warning,
                fontFamily: theme.fontSans,
                fontSize: 9,
                fontWeight: 700,
                lineHeight: 1,
                letterSpacing: 0.2,
                padding: "2px 5px",
                borderRadius: 9,
                whiteSpace: "nowrap",
              })}
            >
              <span aria-hidden="true">&#x21BA;</span>
              <span aria-hidden="true">&#xD7;{retryAttempts}</span>
            </div>
          )}

          {/* Diamond for decider nodes — proper diamond via clip-path */}
          {isDecider ? (
            <div data-fp="stage-node-body" style={sx({ position: "relative", width: 120, height: 72, color: textColor, filter: v("--fp-node-shape-shadow", "none") })}>
              {/* Diamond shape layer */}
              <div
                style={sx({
                  position: "absolute",
                  inset: 0,
                  background: bg,
                  clipPath: "polygon(50% 0%, 100% 50%, 50% 100%, 0% 50%)",
                  border: "none",
                  boxShadow: shadow,
                  transition: suppressMotion ? "none" : "all 0.3s ease",
                })}
              />
              {/* Border layer — slightly larger diamond behind */}
              <div
                style={sx({
                  position: "absolute",
                  inset: `calc(-1 * ${v("--fp-node-border-width", "2px")})`,
                  clipPath: "polygon(50% 0%, 100% 50%, 50% 100%, 0% 50%)",
                  background: borderColor,
                  zIndex: -1,
                  ...(isLazyUnresolved ? {
                    background: "transparent",
                    // Dashed border via SVG for clip-path (CSS border doesn't work with clip-path)
                  } : {}),
                })}
              />
              {/* Content — centered on top of diamond */}
              <div
                style={sx({
                  position: "absolute",
                  inset: 0,
                  display: "flex",
                  flexDirection: "column",
                  alignItems: "center",
                  justifyContent: "center",
                  gap: 1,
                  fontFamily: theme.fontSans,
                  zIndex: 1,
                })}
              >
                <div style={sx({ display: "flex", alignItems: "center", gap: 4 })}>
                  {effectiveIcon && <StageIcon type={effectiveIcon} color={textColor} unstyled={unstyled} size={unstyled ? undefined : iconFootprint} />}
                  {!effectiveIcon && (
                    <span style={sx({ fontSize: 9, color: textColor })}>&#x25C7;</span>
                  )}
                  <span
                    style={sx({
                      fontSize: 11,
                      fontWeight: 600,
                      color: textColor,
                      whiteSpace: "nowrap",
                    })}
                  >
                    {label}
                  </span>
                </div>
                {description && (
                  <span
                    style={sx({
                      fontSize: 8,
                      fontWeight: 400,
                      color: textColor,
                      opacity: 0.7,
                      whiteSpace: "nowrap",
                      overflow: "hidden",
                      textOverflow: "ellipsis",
                      maxWidth: 100,
                    })}
                  >
                    {description}
                  </span>
                )}
                {showStageId && stageId && (
                  <span
                    style={sx({
                      fontSize: 8,
                      fontFamily: theme.fontMono,
                      color: textColor,
                      opacity: 0.55,
                      whiteSpace: "nowrap",
                      overflow: "hidden",
                      textOverflow: "ellipsis",
                      maxWidth: 100,
                    })}
                    title={`stageId: ${stageId}`}
                  >
                    {stageId}
                  </span>
                )}
              </div>
            </div>
          ) : (
            /* Standard rectangular node */
            <div
              data-fp="stage-node-body"
              style={sx({
                background: bg,
                color: textColor,
                border: `${borderWidth} ${borderStyle} ${borderColor}`,
                borderRadius: nodeRadius,
                padding: description
                  ? `${Math.round(6 * sizeScale)}px ${Math.round(12 * sizeScale)}px`
                  : `${Math.round(7 * sizeScale)}px ${Math.round(14 * sizeScale)}px`,
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                gap: description ? 2 : 0,
                boxShadow: shadow,
                transition: suppressMotion ? "none" : "all 0.3s ease",
                fontFamily: theme.fontSans,
                minWidth: 100,
                justifyContent: "center",
              })}
            >
              <div style={sx({ display: "flex", alignItems: "center", gap: 6 })}>
                {/* Semantic icon (lazy nodes default to cloud icon) */}
                {effectiveIcon && <StageIcon type={effectiveIcon} color={textColor} unstyled={unstyled} size={unstyled ? undefined : iconFootprint} />}

                {/* State icon */}
                {done && !effectiveIcon && (
                  <span style={sx({ fontSize: 10, color: textColor })}>&#x2713;</span>
                )}
                {active && !effectiveIcon && (
                  <span
                    style={sx({
                      width: 8,
                      height: 8,
                      borderRadius: "50%",
                      background: "#fff",
                      animation: suppressMotion ? "none" : "fp-blink 1s ease-in-out infinite",
                      flexShrink: 0,
                    })}
                  />
                )}
                {error && !effectiveIcon && (
                  <span style={sx({ fontSize: 10, color: textColor })}>&#x2717;</span>
                )}

                <span
                  style={sx({
                    fontSize: Math.round(13 * sizeScale),
                    fontWeight: isHero ? 700 : 500,
                    color: textColor,
                    whiteSpace: "nowrap",
                  })}
                >
                  {label}
                </span>
                {/* Subflow indicator — nested boxes icon */}
                {isSubflow && (
                  <span
                    style={sx({
                      display: "inline-flex",
                      alignItems: "center",
                      justifyContent: "center",
                      width: 16,
                      height: 16,
                      borderRadius: 3,
                      border: `1.5px solid ${textColor}`,
                      position: "relative",
                      opacity: 0.7,
                      flexShrink: 0,
                    })}
                  >
                    <span
                      style={sx({
                        width: 8,
                        height: 8,
                        borderRadius: 2,
                        border: `1px solid ${textColor}`,
                      })}
                    />
                  </span>
                )}
              </div>
              {/* Description subtitle */}
              {description && (
                <span
                  style={sx({
                    fontSize: 10,
                    fontWeight: 400,
                    color: textColor,
                    opacity: 0.7,
                    whiteSpace: "nowrap",
                    overflow: "hidden",
                    textOverflow: "ellipsis",
                    maxWidth: 160,
                  })}
                >
                  {description}
                </span>
              )}
              {/* Stage ID caption — toggled by `showStageId`. Teaches the
                  runtimeStageId convention; recorders key their data by
                  this ID so consumers can render any recorder's per-stage
                  output by lookup. */}
              {showStageId && stageId && (
                <span
                  style={sx({
                    fontSize: 9,
                    fontFamily: theme.fontMono,
                    color: textColor,
                    opacity: 0.55,
                    whiteSpace: "nowrap",
                    overflow: "hidden",
                    textOverflow: "ellipsis",
                    maxWidth: 160,
                  })}
                  title={`stageId: ${stageId}`}
                >
                  {stageId}
                </span>
              )}
            </div>
          )}
        </div>
      </div>
      <Handle type="source" position={Position.Bottom} style={sx({ opacity: 0 })} />
    </>
  );
});
